content.css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent;
}
.snow-empty-state {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: var(--snow-radius, 18px);
  background: var(--snow-card-bg, #FFFFFF);
  color: var(--snow-ink-secondary, #6B7280);
  font-size: 12px;
  text-align: center;
  padding: 16px;
  border: 1px dashed rgba(0, 0, 0, 0.1);
}
.snow-empty-state .snow-empty-title {
  font-weight: 600;
  color: var(--snow-ink, #111827);
  font-size: 13px;
}
.snow-table-host {
  --snow-primary: #007AFF;
  --snow-secondary: #AF52DE;
  --snow-tertiary: #00C7BE;
  --snow-positive: #34C759;
  --snow-warning: #FF9500;
  --snow-negative: #FF3B30;
  --snow-dark: #1C1C1E;
  --snow-ink: #111827;
  --snow-ink-secondary: #6B7280;
  --snow-ink-muted: #9CA3AF;
  --snow-on-dark: #FFFFFF;
  --snow-card-bg: #FFFFFF;
  --snow-border: #E5E7EB;
  --snow-radius: 18px;
  --snow-hover-bg: rgba(0, 122, 255, 0.055);
  --snow-hover-border: rgba(0, 122, 255, 0.14);
  --snow-selected-bg: rgba(0, 122, 255, 0.09);
  --snow-selected-border: rgba(0, 122, 255, 0.35);
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  color: var(--snow-ink, #111827);
  padding: 0;
  margin: 0;
  background: transparent;
  overflow: hidden;
}
.snow-table-host *,
.snow-table-host *::before,
.snow-table-host *::after {
  box-sizing: border-box;
}
.snow-table-card {
  width: 100%;
  height: 100%;
  background: var(--snow-card-bg, #FFFFFF);
  border-radius: var(--snow-radius, 18px);
  padding: 18px 24px 16px 24px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.snow-table-header-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
  flex-shrink: 0;
}
.snow-table-title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.snow-table-title {
  font-size: 14.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--snow-ink, #111827);
}
.snow-table-count-pill {
  font-size: 11px;
  font-weight: 500;
  color: var(--snow-ink-secondary, #6B7280);
  background: rgba(0, 0, 0, 0.045);
  padding: 3px 9px;
  border-radius: 999px;
}
.snow-table-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.045);
  color: var(--snow-ink-secondary, #6B7280);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.snow-table-cols-header {
  display: grid;
  align-items: center;
  gap: 12px;
  padding: 0 14px 8px 14px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--snow-ink-muted, #9CA3AF);
  flex-shrink: 0;
}
.snow-col-hdr-btn {
  border: none;
  background: transparent;
  padding: 0;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Display", "Inter", Roboto, Helvetica, Arial, sans-serif;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--snow-ink-muted, #9CA3AF);
  text-align: left;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color 200ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-col-hdr-btn.is-numeric,
.snow-col-hdr-btn.is-status {
  justify-content: flex-end;
  text-align: right;
}
.snow-col-hdr-btn:hover,
.snow-col-hdr-btn.is-sorted {
  color: var(--snow-ink, #111827);
  font-weight: 600;
}
.snow-table-rows-scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 2px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.snow-table-rows-scroll::-webkit-scrollbar {
  width: 5px;
}
.snow-table-rows-scroll::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.12);
  border-radius: 999px;
}
@keyframes snowRowFadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.snow-table-pill-row {
  display: grid;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 7px 14px;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.024);
  border: 1px solid transparent;
  cursor: pointer;
  flex-shrink: 0;
  animation: snowRowFadeIn 420ms cubic-bezier(0.22, 1, 0.36, 1) both;
  transition: background-color 240ms cubic-bezier(0.22, 1, 0.36, 1), border-color 240ms cubic-bezier(0.22, 1, 0.36, 1), transform 240ms cubic-bezier(0.22, 1, 0.36, 1), opacity 240ms cubic-bezier(0.22, 1, 0.36, 1);
}
.snow-table-pill-row:hover {
  background: var(--snow-hover-bg, rgba(0, 122, 255, 0.055));
  border-color: var(--snow-hover-border, rgba(0, 122, 255, 0.14));
  transform: translateX(2px);
}
.snow-table-pill-row.is-selected {
  background: var(--snow-selected-bg, rgba(0, 122, 255, 0.09));
  border-color: var(--snow-selected-border, rgba(0, 122, 255, 0.35));
}
.snow-table-pill-row.is-dimmed {
  opacity: 0.45;
}
.snow-cell-primary {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.snow-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10.5px;
  font-weight: 700;
  flex-shrink: 0;
  letter-spacing: 0.02em;
}
.snow-cell-primary-text {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--snow-ink, #111827);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.snow-cell-text {
  font-size: 12px;
  color: var(--snow-ink-secondary, #6B7280);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.snow-cell-num {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--snow-ink, #111827);
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.snow-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  justify-self: end;
}
.snow-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}
